arguments.new_str:
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using ResearchAgent;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

var modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(NoteTakingTool.AddNote),
    AIFunctionFactory.Create(NoteTakingTool.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times to gather diverse information.
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a
           well-structured summary with key points and sources.
        Always search at least 2-3 times with different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("🔍 Research Agent");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    Console.WriteLine($"\n📚 Researching: {input}\n");

    try
    {
        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {input}");

        Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
        Console.WriteLine(response.Text);
        Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"❌ Error: {ex.Message}");
    }

    NoteTakingTool.Clear();
    Console.WriteLine("\nEnter another topic (or 'quit' to exit):");
    Console.Write("> ");
}

