using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Simulated web search tool that the agent uses to find information.
/// Replace the implementation with a real search API (Bing, Google, etc.) for production use.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a given query. Returns a list of search results with titles, snippets, and URLs.")]
    public static async Task<IReadOnlyList<SearchResult>> SearchAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (default: 5)")] int maxResults = 5)
    {
        // This is a simulated search implementation.
        // In production, replace with a real search API such as:
        //   - Bing Web Search API: https://learn.microsoft.com/en-us/bing/search-apis/bing-web-search
        //   - Google Custom Search API: https://developers.google.com/custom-search
        //   - Brave Search API: https://brave.com/search/api/

        await Task.Delay(100); // Simulate network latency

        var simulatedResults = GenerateSimulatedResults(query, maxResults);

        Console.WriteLine($"  🌐 Web search: \"{query}\" → {simulatedResults.Count} results");

        return simulatedResults;
    }

    private static List<SearchResult> GenerateSimulatedResults(string query, int maxResults)
    {
        var results = new List<SearchResult>();
        var queryLower = query.ToLowerInvariant();
        var hash = query.GetHashCode();

        for (int i = 0; i < Math.Min(maxResults, 5); i++)
        {
            results.Add(new SearchResult
            {
                Title = $"Result {i + 1}: Information about {query}",
                Snippet = $"This article discusses {query} and provides detailed insights into the topic. "
                        + $"Key findings suggest that {query} is an important area of study with multiple perspectives. "
                        + $"Researchers have noted significant developments in recent years.",
                Url = $"https://example.com/article/{Math.Abs(hash + i)}"
            });
        }

        return results;
    }
}

public class SearchResult
{
    public required string Title { get; set; }
    public required string Snippet { get; set; }
    public required string Url { get; set; }

    public override string ToString() => $"[{Title}]({Url}): {Snippet}";
}

using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// Note-taking tool that allows the agent to record and retrieve research findings.
/// </summary>
public static class NoteTakingTool
{
    private static readonly List<Note> Notes = [];

    [Description("Adds a research note. Use this to record key findings, facts, or observations during research.")]
    public static string AddNote(
        [Description("The content of the note to record")] string content,
        [Description("The source URL or reference for this note")] string? source = null)
    {
        var note = new Note
        {
            Content = content,
            Source = source,
            Timestamp = DateTime.UtcNow
        };

        Notes.Add(note);
        Console.WriteLine($"  📝 Note added: \"{Truncate(content, 60)}\"");

        return $"Note #{Notes.Count} saved successfully.";
    }

    [Description("Retrieves all research notes taken so far. Use this to review findings before writing a summary.")]
    public static IReadOnlyList<Note> GetNotes()
    {
        Console.WriteLine($"  📋 Retrieved {Notes.Count} note(s)");
        return Notes.AsReadOnly();
    }

    /// <summary>Clears all notes (used between research sessions).</summary>
    public static void Clear() => Notes.Clear();

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..(maxLength - 3)] + "...";
}

public class Note
{
    public required string Content { get; set; }
    public string? Source { get; set; }
    public DateTime Timestamp { get; set; }

    public override string ToString() =>
        Source is not null
            ? $"[{Timestamp:HH:mm:ss}] {Content} (Source: {Source})"
            : $"[{Timestamp:HH:mm:ss}] {Content}";
}

